// Everything downstream needs a stable identifier that survives every
// success and failure branch, created before any API/OCR call is made.
const correlationId =
  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : `local-${Date.now()}-${Math.random().toString(36).slice(2)}`;

const item = $input.first();
const body = item.json.body || {};
// "data" matches the unmodified "fix base64" node's binaryPropertyName.
const invoiceFile = item.binary ? item.binary.data : undefined;

const demoModeRequested = body.demoMode === "true" || body.demoMode === true;
const submittedOrganizationId =
  typeof body.organizationId === "string" && body.organizationId.trim() !== ""
    ? body.organizationId.trim()
    : null;
// Never a silent fallback -- only demoMode=true selects the fictional org.
const organizationId =
  submittedOrganizationId || (demoModeRequested ? "unternehmen-x-demo" : null);

return [
  {
    json: {
      correlationId,
      receivedAt: new Date().toISOString(),
      hasFile: Boolean(invoiceFile),
      filename: invoiceFile ? invoiceFile.fileName : null,
      mimeType: invoiceFile ? invoiceFile.mimeType : null,
      organizationId,
      demoModeRequested,
    },
    binary: item.binary,
  },
];

// Deterministic 4xx-shaped input/contract checks -- no OCR call has been
// made yet, so nothing here is a "technical" failure and nothing here is
// ever retried.
const ctx = $input.first().json;

if (!ctx.hasFile) {
  return [{ json: { ...ctx, valid: false, errorCode: "MISSING_INVOICE_FILE", explanation: "No PDF binary field named 'data' was present in the upload. Not retried: this is an input/contract error, not a service failure." } }];
}
if (!ctx.organizationId) {
  return [{ json: { ...ctx, valid: false, errorCode: "ORGANIZATION_CONTEXT_REQUIRED", explanation: "organizationId was not provided and demoMode was not set. Pass organizationId explicitly, or demoMode=true to use the fictional unternehmen-x-demo organization. Not retried: this is an input/contract error, not a service failure." } }];
}
return [{ json: { ...ctx, valid: true } }];

const ctx = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "Validate Upload Request",
    errorCode: ctx.errorCode,
    explanation: ctx.explanation,
    invoice: null,
    controls: null,
    organizationId: ctx.organizationId,
  },
}];

// TEMPORARY: mirrors facturx/phase1/organization_master_data.py's buyer
// blocks only (name/street/postalCode/city/countryCode). There is no API
// endpoint that exposes organization master data to an external caller,
// and the real Phase 1 API cannot consume OCR-extracted fields at all yet
// (POST /v1/invoices/process only accepts a file upload; the shipped PDF
// adapter is MockPdfExtractionAdapter, keyed by the SHA-256 of the bytes,
// with no injection seam for an n8n-produced OCR result). This object MUST
// be kept in sync with organization_master_data.py by hand until a real
// adapter or a master-data lookup endpoint exists -- see the README's
// "Missing API contract" section for the exact convergence requirement.
const BUYER_PROFILES = {
  "unternehmen-x-demo": {
    name: "Unternehmen X",
    street: "Musterweg 10",
    postalCode: "04109",
    city: "Leipzig",
    countryCode: "DE",
  },
  "unternehmen-y-demo": {
    name: "Unternehmen Y",
    street: "Industriestrasse 20",
    postalCode: "01067",
    city: "Dresden",
    countryCode: "DE",
  },
};

const ctx = $input.first().json;
const profile = BUYER_PROFILES[ctx.organizationId] || null;

return [
  {
    json: {
      ...ctx,
      organizationProfileKnown: profile !== null,
      buyerMasterData: profile,
    },
    binary: $input.first().binary,
  },
];

const ctx = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "Resolve Organization Profile (temporary mirror)",
    errorCode: "ORGANIZATION_CONTEXT_UNKNOWN",
    explanation: `organizationId ${JSON.stringify(ctx.organizationId)} is not a known fictional organization profile. No silent fallback -- pass a recognized organizationId, or demoMode=true for unternehmen-x-demo.`,
    invoice: null,
    controls: null,
    organizationId: ctx.organizationId,
  },
}];

const binaryPropertyName = 'data';
const result = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryPropertyName);

  result.push({
    json: {
      pdfMimeType: 'application/pdf',
      pdfBase64: buffer.toString('base64')
    }
  });
}

return result;

return items.map(item => {
  return {
    json: {
      geminiRequest: {
        contents: [
          {
            parts: [
              {
                inline_data: {
                  mime_type: 'application/pdf',
                  data: item.json.pdfBase64
                }
              },
              {
                text: `Extract invoice header information from this PDF and return JSON only.

Important context:
- The expected buyer company is: Unternehmen X
- The buyer may use one of these approved addresses:
  - Musterweg 10, 04109 Leipzig, Germany
  - Musterweg 12, 04109 Leipzig, Germany
- The buyer VAT ID is: DE450224353

Critical extraction rules:
1. Distinguish clearly between seller and buyer.
2. Do not confuse the buyer VAT ID with the seller VAT ID.
3. If a VAT ID belongs to Unternehmen X, return it as "VAT-ID (Buyer)".
4. Extract the supplier VAT ID separately as "VAT-ID (Seller)".
5. If only one VAT ID is visible, decide whether it belongs to the seller or buyer based on the company name and address nearby.
6. If the seller VAT ID cannot be identified with confidence, return "not found" for "VAT-ID (Seller)".
7. Output JSON only. Do not add explanations or markdown fences.

Return exactly one JSON object with these fields:
{
  "Invoice No": "string",
  "Invoice Date": "string",
  "VAT-ID (Seller)": "string",
  "VAT-ID (Buyer)": "string",
  "Name (Seller)": "string",
  "Address (Seller)": "string",
  "Zip (Seller)": "string",
  "City (Seller)": "string",
  "Country (Seller)": "string",
  "Name (Buyer)": "string",
  "Address (Buyer)": "string",
  "Zip (Buyer)": "string",
  "City (Buyer)": "string",
  "Country (Buyer)": "string"
}

If a field is missing, return "not found".`
              }
            ]
          }
        ]
      }
    }
  };
});

const ctx = $('Build Run Context').item.json;
const ctxErr = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "File-Based OCR with Gemini 2.5",
    errorCode: "OCR_SERVICE_UNAVAILABLE",
    explanation: (ctxErr.error && (ctxErr.error.message || ctxErr.error)) || ctxErr.message || "The Gemini OCR/LLM service did not respond after the bounded retry.",
    invoice: null,
    controls: null,
    organizationId: ctx.organizationId,
  },
}];

function extractTextFromGeminiResponse(item) {
  const j = item.json || {};

  if (
    Array.isArray(j.candidates) &&
    j.candidates[0] &&
    j.candidates[0].content &&
    Array.isArray(j.candidates[0].content.parts) &&
    j.candidates[0].content.parts[0] &&
    typeof j.candidates[0].content.parts[0].text === 'string'
  ) {
    return j.candidates[0].content.parts[0].text;
  }

  throw new Error('Could not find Gemini text output in expected response fields.');
}

function stripMarkdownFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function ensureField(obj, key) {
  return typeof obj[key] === 'string' && obj[key].trim()
    ? obj[key].trim()
    : 'not found';
}

return items.map(item => {
  const rawText = extractTextFromGeminiResponse(item);
  const cleaned = stripMarkdownFences(rawText);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Gemini output is not valid JSON. Raw output: ${cleaned}`);
  }

  const normalized = {
    'Invoice No': ensureField(parsed, 'Invoice No'),
    'Invoice Date': ensureField(parsed, 'Invoice Date'),
    'VAT-ID (Seller)': ensureField(parsed, 'VAT-ID (Seller)'),
    'VAT-ID (Buyer)': ensureField(parsed, 'VAT-ID (Buyer)'),
    'Name (Seller)': ensureField(parsed, 'Name (Seller)'),
    'Address (Seller)': ensureField(parsed, 'Address (Seller)'),
    'Zip (Seller)': ensureField(parsed, 'Zip (Seller)'),
    'City (Seller)': ensureField(parsed, 'City (Seller)'),
    'Country (Seller)': ensureField(parsed, 'Country (Seller)'),
    'Name (Buyer)': ensureField(parsed, 'Name (Buyer)'),
    'Address (Buyer)': ensureField(parsed, 'Address (Buyer)'),
    'Zip (Buyer)': ensureField(parsed, 'Zip (Buyer)'),
    'City (Buyer)': ensureField(parsed, 'City (Buyer)'),
    'Country (Buyer)': ensureField(parsed, 'Country (Buyer)')
  };

  return {
    json: {
      invoice_extracted: normalized,
      gemini_raw_text: rawText
    }
  };
});

const ctx = $('Build Run Context').item.json;
const ctxErr = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "Gemini Output Parser",
    errorCode: "OCR_OUTPUT_PARSE_FAILED",
    explanation: (ctxErr.error && (ctxErr.error.message || ctxErr.error)) || ctxErr.message || "Gemini's response could not be parsed into the expected JSON shape.",
    invoice: null,
    controls: null,
    organizationId: ctx.organizationId,
  },
}];

// TEMPORARY: mirrors the dotted-path fieldEvidence shape from
// facturx/phase1/normalize/pdf_adapter.py (method/confidence/locator/
// rawValue/state) so this stays trivially convergeable once a real adapter
// exists -- but the confidence values below are NOT calibrated. Gemini's
// structured-JSON output carries no native per-field confidence.
//
// Every field Gemini reports as a real value gets a fixed placeholder
// confidence (0.85, just above the 0.70 default threshold used everywhere
// else in this project). Every field Gemini reports as "not found" is
// treated as NOT_EXTRACTED (confidence 0.0, state "not_extracted"), NOT as
// a confirmed absence -- there is no calibrated signal to trust an LLM's
// own "not found" claim as a real business fact yet. This always forces
// not_reliable/nicht_pruefbar for that field, never a confident
// MISSING_FIELD failure, matching the project-wide rule that low-confidence
// or missing OCR fields must route to human review, never an automatic pass.
const PLACEHOLDER_FOUND_CONFIDENCE = 0.85;
const parsed = $input.first().json;
const g = parsed.invoice_extracted;

function emit(rawValue, locator) {
  const found = typeof rawValue === "string" && rawValue.trim() && rawValue.trim().toLowerCase() !== "not found";
  return {
    value: found ? rawValue.trim() : null,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}

const buyerName = emit(g["Name (Buyer)"], "invoice.buyer.name");
const buyerStreet = emit(g["Address (Buyer)"], "invoice.buyer.address.street");
const buyerPostal = emit(g["Zip (Buyer)"], "invoice.buyer.address.postalCode");
const buyerCity = emit(g["City (Buyer)"], "invoice.buyer.address.city");
const buyerCountry = emit(g["Country (Buyer)"], "invoice.buyer.address.countryCode");

const fieldEvidence = {
  "invoice.buyer.name": buyerName.evidence,
  "invoice.buyer.address.street": buyerStreet.evidence,
  "invoice.buyer.address.postalCode": buyerPostal.evidence,
  "invoice.buyer.address.city": buyerCity.evidence,
  "invoice.buyer.address.countryCode": buyerCountry.evidence,
};

function orNull(v) {
  return v === "not found" ? null : v;
}

const invoice = {
  invoiceNumber: orNull(g["Invoice No"]),
  issueDate: orNull(g["Invoice Date"]),
  supplier: {
    name: orNull(g["Name (Seller)"]),
    vatId: orNull(g["VAT-ID (Seller)"]),
    address: {
      street: orNull(g["Address (Seller)"]),
      postalCode: orNull(g["Zip (Seller)"]),
      city: orNull(g["City (Seller)"]),
      countryCode: orNull(g["Country (Seller)"]),
    },
  },
  buyer: {
    name: buyerName.value,
    vatId: orNull(g["VAT-ID (Buyer)"]),
    address: {
      street: buyerStreet.value,
      postalCode: buyerPostal.value,
      city: buyerCity.value,
      countryCode: buyerCountry.value,
    },
  },
};

const ctx = $('Build Run Context').item.json;
const org = $('Resolve Organization Profile (temporary mirror)').item.json;

return [
  {
    json: {
      correlationId: ctx.correlationId,
      organizationId: ctx.organizationId,
      buyerMasterData: org.buyerMasterData,
      invoice,
      fieldEvidence,
      geminiRawText: parsed.gemini_raw_text,
    },
  },
];

// TEMPORARY: replicates facturx/phase1/controls/executor.py::evaluate_org_001
// and its _check/_combine/_normalize_for_match helpers exactly (same 5
// fields, same 0.70 confidence threshold, same case/whitespace-insensitive
// comparison, same severity/reason-code shape) so this control's output is
// structurally interchangeable with the real one -- see the README for what
// a real convergence would require.
const THRESHOLD = 0.70;
const CONTROL_ID = "ORG-001";
const TITLE = "Stammdatenabgleich Rechnungsempfänger";
const RULE_VERSION = "1.0.0";

function normalizeForMatch(value) {
  return (value || "").toString().trim().toLowerCase().replace(/\s+/g, " ");
}

function checkField(value, evidence) {
  const confidence = evidence.confidence;
  if (confidence < THRESHOLD) {
    return {
      outcome: "not_reliable", reasonCodes: ["LOW_CONFIDENCE_EXTRACTION"], evidenceRefs: [evidence.locator],
      message: `${evidence.locator}: extraction confidence ${confidence.toFixed(2)} is below the ${THRESHOLD.toFixed(2)} reliability threshold.`,
    };
  }
  if (value === null || value === undefined || (typeof value === "string" && !value.trim())) {
    return { outcome: "failed", reasonCodes: ["MISSING_FIELD"], evidenceRefs: [evidence.locator], message: `${evidence.locator}: required value is missing.` };
  }
  return { outcome: "passed", reasonCodes: [], evidenceRefs: [evidence.locator], message: null };
}

function combine(parts) {
  const outcomes = parts.map((p) => p.outcome);
  const reasonCodes = [...new Set(parts.flatMap((p) => p.reasonCodes))].sort();
  const evidenceRefs = [...new Set(parts.flatMap((p) => p.evidenceRefs))].sort();
  const messages = parts.map((p) => p.message).filter(Boolean);
  const combinedMessage = messages.length ? messages.join(" ") : null;
  if (outcomes.includes("not_reliable")) return { outcome: "not_reliable", reasonCodes, evidenceRefs, message: combinedMessage };
  if (outcomes.includes("failed")) return { outcome: "failed", reasonCodes, evidenceRefs, message: combinedMessage };
  return { outcome: "passed", reasonCodes: [], evidenceRefs, message: null };
}

const ctx = $input.first().json;
const invoice = ctx.invoice;
const fieldEvidence = ctx.fieldEvidence;
const masterData = ctx.buyerMasterData;

const checks = [
  checkField(invoice.buyer.name, fieldEvidence["invoice.buyer.name"]),
  checkField(invoice.buyer.address.street, fieldEvidence["invoice.buyer.address.street"]),
  checkField(invoice.buyer.address.postalCode, fieldEvidence["invoice.buyer.address.postalCode"]),
  checkField(invoice.buyer.address.city, fieldEvidence["invoice.buyer.address.city"]),
  checkField(invoice.buyer.address.countryCode, fieldEvidence["invoice.buyer.address.countryCode"]),
];
const combined = combine(checks);

let result;
if (combined.outcome !== "passed") {
  result = {
    controlId: CONTROL_ID, title: TITLE, outcome: combined.outcome,
    severity: "blocking", reasonCodes: combined.reasonCodes, evidenceRefs: combined.evidenceRefs,
    ruleVersion: RULE_VERSION, message: combined.message, details: null,
  };
} else {
  const fieldPairs = [
    ["invoice.buyer.name", invoice.buyer.name, masterData.name],
    ["invoice.buyer.address.street", invoice.buyer.address.street, masterData.street],
    ["invoice.buyer.address.postalCode", invoice.buyer.address.postalCode, masterData.postalCode],
    ["invoice.buyer.address.city", invoice.buyer.address.city, masterData.city],
    ["invoice.buyer.address.countryCode", invoice.buyer.address.countryCode, masterData.countryCode],
  ];
  const mismatches = fieldPairs
    .filter(([, actual, expected]) => normalizeForMatch(actual) !== normalizeForMatch(expected))
    .map(([f, actual, expected]) => ({ field: f, expected, actual }));

  if (mismatches.length > 0) {
    const message = "Buyer data does not match approved organization master data: " +
      mismatches.map((m) => `${m.field} expected ${JSON.stringify(m.expected)}, got ${JSON.stringify(m.actual)}`).join("; ");
    result = {
      controlId: CONTROL_ID, title: TITLE, outcome: "failed", severity: "blocking",
      reasonCodes: ["MASTER_DATA_MISMATCH"], evidenceRefs: combined.evidenceRefs,
      ruleVersion: RULE_VERSION, message, details: { mismatches },
    };
  } else {
    result = {
      controlId: CONTROL_ID, title: TITLE, outcome: "passed", severity: "none",
      reasonCodes: [], evidenceRefs: combined.evidenceRefs, ruleVersion: RULE_VERSION,
      message: null, details: null,
    };
  }
}

return [{ json: { ...ctx, org001: result } }];

// Aggregation mirrors facturx/phase1/controls/aggregate.py's mapping for a
// single control exactly: not_reliable -> nicht_pruefbar/prioritized_review,
// failed+blocking -> klaerung_erforderlich/prioritized_review, passed ->
// unauffaellig/standard_review. "technical_review" (used elsewhere in this
// workflow) is deliberately NOT one of the real API's routing values -- it
// only appears upstream of this node, for genuine service/input failures.
const ctx = $input.first().json;
const org001 = ctx.org001;

let status, routing;
if (org001.outcome === "not_reliable") {
  status = "nicht_pruefbar";
  routing = "prioritized_review";
} else if (org001.outcome === "failed") {
  status = "klaerung_erforderlich";
  routing = "prioritized_review";
} else {
  status = "unauffaellig";
  routing = "standard_review";
}

return [{
  json: {
    correlationId: ctx.correlationId,
    status,
    routing,
    failedStep: null,
    errorCode: null,
    explanation: null,
    invoice: ctx.invoice,
    controls: [org001],
    organizationId: ctx.organizationId,
  },
}];

// Single convergence point for every success and failure branch. Renders
// self-contained HTML -- the demo audience must never need to inspect raw
// n8n execution JSON. A prominent notice states this is a temporary,
// n8n-side-only implementation (see the workflow-level and README notes).
const r = $input.first().json;

function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

const statusColors = { unauffaellig: "#1b7a3d", klaerung_erforderlich: "#a15c00", nicht_pruefbar: "#a11616" };
const statusColor = statusColors[r.status] || "#444";

let body;
if (r.controls) {
  const inv = r.invoice;
  const rows = r.controls.map((c) => `
    <tr>
      <td>${esc(c.controlId)}</td>
      <td>${esc(c.title)}</td>
      <td>${esc(c.outcome)}</td>
      <td>${esc(c.severity)}</td>
      <td>${esc((c.reasonCodes || []).join(", "))}</td>
      <td>${esc(c.message)}</td>
      <td><pre>${esc(c.details ? JSON.stringify(c.details, null, 2) : "")}</pre></td>
    </tr>`).join("");

  body = `
    <h2>Invoice ${esc(inv.invoiceNumber || "(missing)")} dated ${esc(inv.issueDate || "(missing)")}</h2>
    <p><b>Supplier (as read by OCR/LLM, not verified):</b> ${esc(inv.supplier.name)}</p>
    <p><b>Buyer (as read by OCR/LLM):</b> ${esc(inv.buyer.name)}, ${esc(inv.buyer.address.street)}, ${esc(inv.buyer.address.postalCode)} ${esc(inv.buyer.address.city)}, ${esc(inv.buyer.address.countryCode)}</p>
    <p><b>Organization profile:</b> ${esc(r.organizationId)}</p>
    <h3>Controls</h3>
    <table border="1" cellpadding="6" cellspacing="0">
      <tr><th>Control</th><th>Title</th><th>Outcome</th><th>Severity</th><th>Reason codes</th><th>Message</th><th>Details</th></tr>
      ${rows}
    </table>`;
} else {
  body = `
    <h2>Technical result -- no control was evaluated</h2>
    <p><b>Failed step:</b> ${esc(r.failedStep)}</p>
    <p><b>Error code:</b> ${esc(r.errorCode)}</p>
    <p><b>Explanation:</b> ${esc(r.explanation)}</p>`;
}

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>DigiTax Flow 1b result</title>
<style>
  body { font-family: sans-serif; margin: 2rem; color: #1a1a1a; }
  .banner { padding: 1rem; border-radius: 6px; color: white; background: ${statusColor}; margin-bottom: 1rem; }
  .temp-notice { padding: 1rem; background: #fff3cd; border: 1px solid #d6b656; border-radius: 6px; margin-bottom: 1.5rem; }
  table { border-collapse: collapse; width: 100%; }
  th { background: #eee; text-align: left; }
  pre { white-space: pre-wrap; margin: 0; font-size: 0.85em; }
  .boundary { margin-top: 2rem; padding: 1rem; background: #f5f5f5; border-left: 4px solid #888; }
</style>
</head>
<body>
  <div class="temp-notice">
    <b>Flow 1b is a temporary n8n-side implementation.</b> OCR/LLM extraction
    (Gemini) is real; the ORG-001 evaluation below is computed in n8n, not by
    the Phase 1 API -- POST /v1/invoices/process cannot yet consume
    OCR-extracted fields (its PDF adapter is a mock with no injection seam).
    This result is not yet interchangeable with a real API-issued control
    report. See examples/n8n/README.md for the missing adapter/API contract.
  </div>
  <div class="banner">
    <b>STATUS: ${esc(r.status)}</b> (routing: ${esc(r.routing)})<br>
    Correlation ID: ${esc(r.correlationId)}
  </div>
  ${body}
  <div class="boundary">
    This is a Flow 1b finding for human review only -- it is not an
    approval, rejection, booking, payment, or supplier communication.
  </div>
</body></html>`;

return [{ json: { ...r, html } }];
